<?php /** @var array $p @var array $systems @var array $gaps @var array $history @var ?array $pending @var bool $canDecide */
$crit = '<span class="badge ' . ($p['criticality'] === 'critical' ? 'danger' : ($p['criticality'] === 'high' ? 'warn' : '')) . '">' . e(t('enum.crit.' . $p['criticality'])) . '</span>';
$steps = ['draft', 'pending_approval', 'approved']; $cur = array_search($p['status'], $steps, true); $lateRev = $p['status'] === 'approved' && $p['next_review_due'] && $p['next_review_due'] < date('Y-m-d'); ?>
<div class="page-head"><div><h1><?= icon('layers') ?> <?= e($p['code']) ?> — <?= e($p['name']) ?></h1><p class="sub"><?= $crit ?> <?= $p['archived_at'] ? '<span class="badge">' . e(t('common.archived')) . '</span>' : '' ?><?= $lateRev ? ' <span class="badge danger">' . e(t('bia.review_overdue')) . '</span>' : '' ?></p></div>
  <div class="actions"><a class="btn secondary" href="<?= e(url('bia')) ?>"><?= e(t('common.back')) ?></a>
  <?php if (can('bia.manage')): ?><a class="btn" href="<?= e(url('bia/' . $p['id'] . '/edit')) ?>"><?= e(t('common.edit')) ?></a>
  <?php if ($p['status'] === 'draft' && !$p['archived_at']): ?><form method="post" class="inline" action="<?= e(url('bia/' . $p['id'] . '/submit')) ?>"><?= csrf_field() ?><button class="btn gold" type="submit"><?= e(t('bia.submit')) ?></button></form><?php endif; ?>
  <form method="post" class="inline" action="<?= e(url('bia/' . $p['id'] . '/archive')) ?>" data-confirm="<?= e(t($p['archived_at'] ? 'risk.confirm_restore' : 'risk.confirm_archive')) ?>"><?= csrf_field() ?><button class="btn danger" type="submit"><?= e(t($p['archived_at'] ? 'common.restore' : 'common.archive')) ?></button></form><?php endif; ?></div></div>
<ol class="stepper"><?php foreach ($steps as $i => $s): ?><li class="<?= $i < $cur ? 'done' : ($i === $cur ? 'current' : '') ?>"<?= $i === $cur ? ' aria-current="step"' : '' ?>><?= e(t('enum.bstatus.' . $s)) ?></li><?php endforeach; ?></ol>
<?php if ($gaps): ?><div class="msg error" role="alert"><strong><?= e(t('bia.gaps_title')) ?></strong><ul><?php foreach ($gaps as $g): ?><li><?= e(t('bia.gap_' . $g['kind'], ['system' => $g['system'], 'have' => $g['have'], 'need' => $g['need']])) ?></li><?php endforeach; ?></ul><?= e(t('bia.gaps_hint')) ?></div><?php endif; ?>
<?php if ($pending && $canDecide): ?><section class="card"><h2><?= e(t('appr.decide')) ?></h2><p><?= e(t('appr.requested_by', ['name' => $history[0]['requester'] ?? ''])) ?></p>
<form method="post" action="<?= e(url('approvals/' . $pending['id'] . '/decide')) ?>"><?= csrf_field() ?><input type="hidden" name="back" value="entity">
<div class="field"><label for="comment"><?= e(t('appr.comment')) ?></label><textarea id="comment" name="comment" rows="3"></textarea><p class="hint"><?= e(t('appr.comment_hint')) ?></p></div>
<div class="actions"><button class="btn" name="decision" value="approve" type="submit"><?= e(t('appr.approve')) ?></button><button class="btn danger" name="decision" value="reject" type="submit"><?= e(t('appr.reject')) ?></button></div></form></section>
<?php elseif ($pending): ?><p class="msg info"><?= e(t('appr.waiting')) ?></p><?php endif; ?>
<div class="grid cols-2"><section class="card"><h2><?= e(t('bia.sec_process')) ?></h2><dl class="details"><dt><?= e(t('bia.department')) ?></dt><dd><?= e(lname($p, 'dept')) ?></dd><dt><?= e(t('bia.owner')) ?></dt><dd><?= e($p['owner_name']) ?></dd>
<dt><?= e(t('bia.description')) ?></dt><dd class="pre"><?= e($p['description'] ?? '—') ?></dd><dt><?= e(t('bia.approved_at')) ?></dt><dd><?= e(fdatetime($p['approved_at']) ?: '—') ?></dd><dt><?= e(t('bia.next_review')) ?></dt><dd><?= e(fdate($p['next_review_due']) ?: '—') ?></dd></dl></section>
<section class="card"><h2><?= e(t('bia.sec_impact')) ?></h2><table class="data"><tbody>
<?php foreach (['impact_financial', 'impact_operational', 'impact_legal', 'impact_reputation'] as $k): ?><tr><th scope="row"><?= e(t('bia.' . $k)) ?></th><td class="num"><?= (int)$p[$k] ?> / 5</td></tr><?php endforeach; ?></tbody></table>
<h3 style="margin-top:12px"><?= e(t('bia.sec_recovery')) ?></h3><dl class="details"><dt><?= e(t('bia.mtpd_hours')) ?></dt><dd><?= e(\App\Support\Bia::fmt($p['mtpd_hours'])) ?> <?= e(t('bia.hours')) ?></dd><dt><?= e(t('bia.rto_hours')) ?></dt><dd><?= e(\App\Support\Bia::fmt($p['rto_hours'])) ?> <?= e(t('bia.hours')) ?></dd><dt><?= e(t('bia.rpo_hours')) ?></dt><dd><?= e(\App\Support\Bia::fmt($p['rpo_hours'])) ?> <?= e(t('bia.hours')) ?></dd></dl></section></div>
<section class="card"><h2><?= e(t('bia.sec_dependencies')) ?></h2>
<?php if (!$systems): ?><p class="muted"><?= e(t('bia.no_systems_linked')) ?></p><?php else: ?><div class="table-wrap"><table class="data"><thead><tr><th><?= e(t('bia.id')) ?></th><th><?= e(t('bia.s_name')) ?></th><th class="num"><?= e(t('bia.s_recovery')) ?></th><th class="num"><?= e(t('bia.s_loss')) ?></th></tr></thead><tbody>
<?php foreach ($systems as $s): ?><tr><td><?= e($s['code']) ?></td><td><?= e($s['name']) ?><?= $s['is_active'] ? '' : ' <span class="badge">' . e(t('common.inactive')) . '</span>' ?></td><td class="num"><?= e(\App\Support\Bia::fmt($s['recovery_hours'])) ?></td><td class="num"><?= e(\App\Support\Bia::fmt($s['data_loss_hours'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php if ($p['dependencies']): ?><p class="pre"><?= e($p['dependencies']) ?></p><?php endif; ?></section>
<?php if ($history): ?><section class="card"><h2><?= e(t('appr.history')) ?></h2><div class="table-wrap"><table class="data"><thead><tr><th><?= e(t('appr.requested')) ?></th><th><?= e(t('appr.status')) ?></th><th><?= e(t('appr.decided_by')) ?></th><th><?= e(t('appr.comment')) ?></th></tr></thead><tbody>
<?php foreach ($history as $h): ?><tr><td><?= e(fdatetime($h['requested_at'])) ?> — <?= e($h['requester']) ?></td><td><span class="badge <?= $h['status'] === 'approved' ? 'ok' : ($h['status'] === 'rejected' ? 'danger' : 'warn') ?>"><?= e(t('enum.astatus.' . $h['status'])) ?></span></td><td><?= e($h['decider'] ?? '—') ?> <?= $h['decided_at'] ? '<span class="muted">' . e(fdatetime($h['decided_at'])) . '</span>' : '' ?></td><td class="pre"><?= e($h['comment'] ?? '—') ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
